  1047→    /// Builds a the [`EthTransactionValidator`] without spawning validator tasks.
  1048→    pub fn build<Tx, S>(self, blob_store: S) -> EthTransactionValidator<Client, Tx>
  1049→    where
  1050→        S: BlobStore,
  1051→    {
  1052→        let Self {
  1053→            client,
  1054→            shanghai,
  1055→            cancun,
  1056→            prague,
  1057→            osaka,
  1058→            eip2718,
  1059→            eip1559,
  1060→            eip4844,
  1061→            eip7702,
  1062→            block_gas_limit,
  1063→            tx_fee_cap,
  1064→            minimum_priority_fee,
  1065→            kzg_settings,
  1066→            local_transactions_config,
  1067→            max_tx_input_bytes,
  1068→            max_tx_gas_limit,
  1069→            disable_balance_check,
  1070→            ..
  1071→        } = self;
  1072→
  1073→        let max_blob_count = if prague {
  1074→            BlobParams::prague().max_blobs_per_tx
  1075→        } else {
  1076→            BlobParams::cancun().max_blobs_per_tx
  1077→        };
  1078→
  1079→        let fork_tracker = ForkTracker {
  1080→            shanghai: AtomicBool::new(shanghai),
  1081→            cancun: AtomicBool::new(cancun),
  1082→            prague: AtomicBool::new(prague),
  1083→            osaka: AtomicBool::new(osaka),
  1084→            max_blob_count: AtomicU64::new(max_blob_count),
  1085→        };
  1086→
  1087→        EthTransactionValidator {
  1088→            client,
  1089→            eip2718,
  1090→            eip1559,
  1091→            fork_tracker,
  1092→            eip4844,
  1093→            eip7702,
  1094→            block_gas_limit,
  1095→            tx_fee_cap,
  1096→            minimum_priority_fee,
  1097→            blob_store: Box::new(blob_store),
  1098→            kzg_settings,
  1099→            local_transactions_config,
  1100→            max_tx_input_bytes,
  1101→            max_tx_gas_limit,
  1102→            disable_balance_check,
  1103→            _marker: Default::default(),
  1104→            validation_metrics: TxPoolValidationMetrics::default(),
  1105→        }
  1106→    }
  1107→
  1108→    /// Builds a [`EthTransactionValidator`] and spawns validation tasks via the
  1109→    /// [`TransactionValidationTaskExecutor`]
  1110→    ///
  1111→    /// The validator will spawn `additional_tasks` additional tasks for validation.
  1112→    ///
  1113→    /// By default this will spawn 1 additional task.
  1114→    pub fn build_with_tasks<Tx, T, S>(
  1115→        self,
  1116→        tasks: T,
  1117→        blob_store: S,
  1118→    ) -> TransactionValidationTaskExecutor<EthTransactionValidator<Client, Tx>>
  1119→    where
  1120→        T: TaskSpawner,
  1121→        S: BlobStore,
  1122→    {
  1123→        let additional_tasks = self.additional_tasks;
  1124→        let validator = self.build(blob_store);
  1125→
  1126→        let (tx, task) = ValidationTask::new();
  1127→
  1128→        // Spawn validation tasks, they are blocking because they perform db lookups
  1129→        for _ in 0..additional_tasks {
  1130→            let task = task.clone();
  1131→            tasks.spawn_blocking(Box::pin(async move {
  1132→                task.run().await;
  1133→            }));
  1134→        }
  1135→
  1136→        // we spawn them on critical tasks because validation, especially for EIP-4844 can be quite
  1137→        // heavy
  1138→        tasks.spawn_critical_blocking(
  1139→            "transaction-validation-service",
  1140→            Box::pin(async move {
  1141→                task.run().await;
  1142→            }),
  1143→        );
  1144→
  1145→        let to_validation_task = Arc::new(Mutex::new(tx));
  1146→
  1147→        TransactionValidationTaskExecutor { validator: Arc::new(validator), to_validation_task }
  1148→    }
  1149→}
