  1151→/// Keeps track of whether certain forks are activated
  1152→#[derive(Debug)]
  1153→pub struct ForkTracker {
  1154→    /// Tracks if shanghai is activated at the block's timestamp.
  1155→    pub shanghai: AtomicBool,
  1156→    /// Tracks if cancun is activated at the block's timestamp.
  1157→    pub cancun: AtomicBool,
  1158→    /// Tracks if prague is activated at the block's timestamp.
  1159→    pub prague: AtomicBool,
  1160→    /// Tracks if osaka is activated at the block's timestamp.
  1161→    pub osaka: AtomicBool,
  1162→    /// Tracks max blob count per transaction at the block's timestamp.
  1163→    pub max_blob_count: AtomicU64,
  1164→}
  1165→
  1166→impl ForkTracker {
  1167→    /// Returns `true` if Shanghai fork is activated.
  1168→    pub fn is_shanghai_activated(&self) -> bool {
  1169→        self.shanghai.load(std::sync::atomic::Ordering::Relaxed)
  1170→    }
  1171→
  1172→    /// Returns `true` if Cancun fork is activated.
  1173→    pub fn is_cancun_activated(&self) -> bool {
  1174→        self.cancun.load(std::sync::atomic::Ordering::Relaxed)
  1175→    }
  1176→
  1177→    /// Returns `true` if Prague fork is activated.
  1178→    pub fn is_prague_activated(&self) -> bool {
  1179→        self.prague.load(std::sync::atomic::Ordering::Relaxed)
  1180→    }
  1181→
  1182→    /// Returns `true` if Osaka fork is activated.
  1183→    pub fn is_osaka_activated(&self) -> bool {
  1184→        self.osaka.load(std::sync::atomic::Ordering::Relaxed)
  1185→    }
  1186→
  1187→    /// Returns the max allowed blob count per transaction.
  1188→    pub fn max_blob_count(&self) -> u64 {
  1189→        self.max_blob_count.load(std::sync::atomic::Ordering::Relaxed)
  1190→    }
  1191→}
